define([], function () { var INTERACTION_MIN_SECONDS = 0.25; var SAVE_REASONS = [ 'heartbeat', 'pause', 'seek', 'ended', 'beforeunload', 'pagehide', 'tab', 'visibilitychange', 'reaction', 'note', 'interaction' ]; function finiteSeconds(value) { value = Number(value); return Number.isFinite(value) ? Math.max(0, value) : 0; } function normaliseSaveReason(reason) { reason = String(reason || 'interaction'); return SAVE_REASONS.indexOf(reason) !== -1 ? reason : 'interaction'; } function clampSegmentTimes(start, end, duration) { var max = finiteSeconds(duration); start = finiteSeconds(start); end = Math.max(start, finiteSeconds(end)); if (max > 0) { start = Math.min(start, max); end = Math.min(end, max); } return { start: Math.round(start * 1000) / 1000, end: Math.round(end * 1000) / 1000 }; } function calculateInteractionEnd(start, end, duration, reason) { start = finiteSeconds(start); end = finiteSeconds(end); if (end > start) { return end; } reason = normaliseSaveReason(reason); if (reason !== 'reaction' && reason !== 'note') { return end; } end = start + INTERACTION_MIN_SECONDS; duration = finiteSeconds(duration); if (duration > 0) { end = Math.min(end, duration); } return end; } return { finiteSeconds: finiteSeconds, normaliseSaveReason: normaliseSaveReason, clampSegmentTimes: clampSegmentTimes, calculateInteractionEnd: calculateInteractionEnd }; });
